import{_ as a,o as n,a as p,b as l}from"./app.CIoiBgkh.js";const c="/ascendc.github.io/pr/6199/assets/fixpipe_nz2nz_c_api.DRuFPNZe.png",e="/ascendc.github.io/pr/6199/assets/fixpipe_nz2nz_c_api_950.DAdjrVa4.png",z=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/cube_store_key_features"},{"text":"NZ2NZ","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/NZ2NZ"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/NZ2NZ.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/NZ2NZ.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1789956443000}'),i={name:"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/NZ2NZ.md"};function t(_,s,d,o,r,w){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>NZ2NZ</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵计算的搬出过程中Nz2Nz的核心功能体现为，矩阵计算结果搬出前后保持Nz大分形排布；输出类型转换及Channel Split/Channel Merge可能改变小分形宽度。以下伪代码仅描述未启用通道拆分/合并的逐块地址关系。</p><div data-filter="A3,910b"><p>以如下产品型号为例：</p><div data-filter="A3"><p>Atlas A3系列产品</p></div><div data-filter="910b"><p>Atlas A2系列产品</p></div><p>Nz2Nz转化过程可以参考以下伪代码（src/dst及临时地址均按字节地址计数）：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="n">j</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">m_size</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">src_temp_n_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">L0C_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="w">    </span><span class="n">dst_temp_n_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">DST_element</span><span class="p">);</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="p">((</span><span class="n">n_size</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">15</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span><span class="w"> </span><span class="n">k</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">src_block_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src_temp_n_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">src_stride</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">L0C_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="w">        </span><span class="n">dst_block_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst_temp_n_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dst_stride</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>伪代码使用的参数具体说明如下：</p><ul><li>src表示源操作数搬运的起始地址。</li><li>dst表示目的操作数搬运的起始地址。</li><li>源操作数中Nz矩阵每一行的起始地址为src_temp_n_addr。</li><li>目的操作数中Nz矩阵每一行的起始地址为dst_temp_n_addr。</li><li>在每一行中，以16个数据为粒度进行数据块切分，源操作数每一块数据块的起始地址为src_block_addr，目的操作数中每一数据块起始地址为dst_block_addr。</li></ul><p>以下参数为Nz2Nz用户可配置参数（2201目的步长参数名为dst_stride_dst_d，本文统一记为dst_stride），含义及取值范围参见<a href="../asc_copy_l0c2gm/asc_copy_l0c2gm.html">C API搬出参数</a>：</p><ul><li>m_size与n_size分别表示矩阵M方向和N方向上的维度。</li><li>src_stride表示源Nz矩阵中不同Z分形列的间隔，单位为C0_Size（C0_Size=16*sizeof(T)，T为操作数的数据类型）。</li><li>dst_stride表示目标Nz矩阵中不同Z分形列的间隔，单位为32字节。</li></ul></div><div data-filter="950"><p>以Ascend 950PR&amp;950DT系列产品为例，Nz2Nz转化过程可以参考以下伪代码（src/dst及临时地址均按字节地址计数）：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="n">j</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">m_size</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">src_temp_n_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">L0C_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="w">    </span><span class="n">dst_temp_n_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">DST_element</span><span class="p">);</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="p">((</span><span class="n">n_size</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">15</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span><span class="w"> </span><span class="n">k</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">src_block_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src_temp_n_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">src_stride</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">L0C_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="w">        </span><span class="n">dst_block_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst_temp_n_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dst_stride</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">DST_element</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>伪代码使用的参数具体说明如下：</p><ul><li>src表示源操作数搬运的起始地址。</li><li>dst表示目的操作数搬运的起始地址。</li><li>源操作数中Nz矩阵每一行的起始地址为src_temp_n_addr。</li><li>目的操作数中Nz矩阵每一行的起始地址为dst_temp_n_addr。</li><li>在每一行中，以16个数据为粒度进行数据块切分，源操作数每一块数据块的起始地址为src_block_addr，目的操作数中每一数据块起始地址为dst_block_addr。</li></ul><p>以下参数为Nz2Nz用户可配置参数，含义及取值范围参见<a href="../asc_copy_l0c2gm/asc_copy_l0c2gm.html">C API搬出参数</a>：</p><ul><li>m_size与n_size分别表示矩阵M方向和N方向上的维度。</li><li>src_stride表示源Nz矩阵中不同Z分形列的间隔，单位为C0_Size（C0_Size=16*sizeof(T)，T为操作数的数据类型）。</li><li>dst_stride表示目标Nz矩阵中不同Z分形列的间隔，单位为element。</li></ul></div><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><ul><li>当Nz2Nz与F32 Channel Split特性组合开启时，搬出到GM的Nz分形中的小分形维度为16*8，确保小z分形的大小为512B。</li><li>对于B8数据类型Nz输出时，Channel Merge默认开启，搬出GM/L1 Buffer小分形维度为16*32，确保小z分形的大小为512B。</li><li>对于B4数据类型Nz输出时，Channel Merge默认开启，小分形维度为16*64，确保小z分形的大小为512B。</li><li>目标操作数地址之间不能重叠。</li></ul><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>如下图所示，在L0C Buffer中有一个Nz格式的矩阵，该矩阵N方向上维度为48，M方向上维度为24，经过Nz2Nz转换，将数据格式变为右部分所示排布。</p><div data-filter="A3,910b"><p><strong>图1</strong> Nz2Nz示意图（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）</p><p><img src="`+c+'" alt></p><p>示意图中参数设置示例（通过L0C Buffer搬出接口搬运并去除dummy数据）和解释说明如下：</p><ul><li>当M方向上的数据元素个数不是16的倍数时，源分形可能包含补齐的dummy数据，搬出按m_size选择有效行，dummy行不写入目标位置。矩阵块被定义为连续的16*16的数据块，数据块的个数为M/16向上取整，矩阵块的长度为M*16*sizeof(T)，T是数据类型。</li><li>n_size=48，表示源Nz矩阵中待搬运矩阵在N方向上的大小为48个元素。</li><li>m_size=24，表示源Nz矩阵中待搬运矩阵在M方向上的大小为24个元素。</li><li>src_stride=64，表示源Nz矩阵中待搬运矩阵相邻Z排布的起始地址偏移，即下图中第一个Z排布的起始地址与第二个Z排布的起始地址之间的间隔为64 * C0_Size。</li><li>dst_stride = 40，表示目的Nz矩阵中相邻Z排布的起始地址偏移，即下图中第一个Z排布的起始地址与第二个Z排布的起始地址之间的间隔为40*32字节。</li></ul></div><div data-filter="950"><p><strong>图2</strong> Nz2Nz示意图（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</p><p><img src="'+e+'" alt></p><p>示意图中参数设置示例（通过L0C Buffer搬出接口搬运并去除dummy数据）和解释说明如下：</p><ul><li>当M方向上的数据元素个数不是16的倍数时，源分形可能包含补齐的dummy数据，搬出按m_size选择有效行，dummy行不写入目标位置。矩阵块被定义为连续的16*16的数据块，数据块的个数为M/16向上取整，矩阵块的长度为M*16*sizeof(T)，T是数据类型。</li><li>n_size=48，表示源Nz矩阵中待搬运矩阵在N方向上的大小为48个元素。</li><li>m_size=24，表示源Nz矩阵中待搬运矩阵在M方向上的大小为24个元素。</li><li>src_stride=64，表示源Nz矩阵中待搬运矩阵相邻Z排布的起始地址偏移，即下图中第一个Z排布的起始地址与第二个Z排布的起始地址之间的间隔为64 * C0_Size。</li><li>dst_stride = 40 * 16，表示目的Nz矩阵中相邻Z排布的起始地址偏移，即下图中第一个Z排布的起始地址与第二个Z排布的起始地址之间的间隔为40*16个元素。</li></ul></div></article></div>',1)])])}const h=a(i,[["render",t]]);export{z as __pageData,h as default};
